function attach(target){if(target==='chat'&&!['active'].includes(state.order)){toast('请在服务进行中发送附件');return}showSheet('添加图片或文件','<p>选择本地截图、图片或文件。</p><input id="upload" type="file" multiple aria-label="选择附件"><p class="small">最多 3 个附件，单个不超过 8 MB。</p>',m=>{q('#upload',m).onchange=async e=>{const files=[...e.target.files];if(!files.length)return;const existing=target==='request'?state.attachments.length:0;if(files.length+existing>3){toast('最多添加 3 个附件');return}if(files.some(f=>f.size>8*1024*1024)){toast('单个文件不能超过 8 MB');return}const items=await Promise.all(files.map(f=>new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,type:f.type,data:reader.result});reader.readAsDataURL(f)})));items.forEach(item=>addAttachment(item,target));closeSheet();render();toast('附件已添加')}})}
