function tagsSheet(){showSheet('添加问题标签','<p>标签由你选择或填写，选填，最多 3 个。</p><div id="tag-options"></div><input type="text" id="custom-tag" maxlength="12" aria-label="自定义问题标签" placeholder="例如：萨克斯、Excel、设备连接"><button class="primary" id="add-tag">添加标签</button>',m=>{const selected=q('#tag-options',m);selected.innerHTML=state.tags.map(t=>'<button class="pill selected" data-tag="'+esc(t)+'">'+esc(t)+' ×</button>').join('');qa('[data-tag]',m).forEach(b=>b.onclick=()=>{state.tags=state.tags.filter(t=>t!==b.dataset.tag);state.tagOrigin='manual';b.remove();save();updateTags()});q('#add-tag',m).onclick=()=>{const t=q('#custom-tag',m).value.trim();if(!t){toast('请先填写标签');return}if(!state.tags.includes(t)){if(state.tags.length>=3){toast('最多添加 3 个标签');return}state.tags.push(t)}state.tagOrigin='manual';closeSheet();render();save()}})}
