 const old=qa('[data-name^="标签/"]').filter(e=>/×/.test(e.dataset.name));if(!old.length)return;old.forEach(e=>e.style.display='none');q('#dynamic-tags')?.remove();
 const group=document.createElement('div');group.id='dynamic-tags';group.className='question-tags';group.style.top=(current==='confirm'?622:579)+'px';
 if(!state.tags.length){const hint=document.createElement('span');hint.className='empty-tags';hint.textContent='添加相关标签（选填）';group.appendChild(hint)}
