function reply(){return}
function send(text){if(state.order==='matching'){toast('请等待服务者实际接单，再开始沟通');return}if(state.order==='none'){toast('请先发起求助');return}const input=q('#chat-input');text=(text??input?.value??'').trim();if(!text){toast('请先输入消息');return}if(text.length>500){toast('消息最多 500 字');return}if(state.order==='completed'||state.order==='cancelled'){toast('服务已结束，可在历史沟通中查看记录');return}state.messages.push({mine:true,text});if(input)input.value='';save();renderChatMessages()}
function renderChatMessages(){let list=q('.chat-list');if(!list)return;list.style.display='block';if(!state.title||state.order==='none'){list.innerHTML='<div style="padding:80px 24px;text-align:center"><p style="font-size:16px;font-weight:700">暂无进行中的求助</p><p style="font-size:13px;color:#5c6c80;margin-top:12px">发起求助并确认接单后，就可以在这里沟通。</p><button class="primary" id="chat-create">发起求助</button></div>';q('#chat-create',list).onclick=()=>navigate('method');return}const items=state.messages||[];list.innerHTML=(items.length?items.map(m=>'<div class="chat-line '+(m.mine?'mine':'')+'"><div class="bubble">'+(m.text?esc(m.text).replace(/\n/g,'<br>'):'')+'</div></div>').join(''):'<div style="padding:80px 24px;text-align:center;color:#5c6c80">等待双方输入第一条消息</div>')+(state.order==='completed'?'<p class="chat-ended">服务已结束，聊天记录仅供查看</p>':'');list.scrollTop=list.scrollHeight}
