function setupVideo(){named('开启状态').forEach(e=>{e.removeAttribute('role');e.removeAttribute('tabindex')});const label=qa('p').find(e=>e.textContent.includes('视频通话中'));if(label)label.textContent='正在获取摄像头和麦克风权限…';leafText('正在进行视频指导','正在建立实时视频连接…')}
function updateCall(){[['通话操作/麦克风',mic],['通话操作/摄像头',camera]].forEach(([n,active])=>named(n).forEach(e=>{const circle=named('圆形触控区',e)[0];if(circle)circle.style.backgroundColor=active?'#22334a':'#dc4c56';e.setAttribute('aria-pressed',String(active))}));const my=named('我的画面窗口')[0];if(my)my.style.opacity=camera?'1':'.4'}
function finishService(){if(!['active','review','completed'].includes(state.order)){toast('当前没有可完成的服务');return}if(state.order==='completed'){toast('服务已结束');return}state.order='review';navigate('review');save()}
function readReview(){const input=q('#review-text');if(input)state.review=input.value;save()}
function setupReview(){const mask=named('评价遮罩')[0];let n=screen.firstElementChild.firstElementChild;while(n&&n!==mask){n.inert=true;n=n.nextElementSibling}const box=named('评价内容输入')[0];if(box){box.removeAttribute('role');box.removeAttribute('tabindex');q('p',box)?.remove();const ta=document.createElement('textarea');ta.id='review-text';ta.className='field review';ta.maxLength=300;ta.placeholder='说说哪些指导对你有帮助…';ta.setAttribute('aria-label','评价内容');ta.value=state.review;ta.oninput=()=>{readReview();const counter=qa('p',box).find(p=>p.textContent.includes('300'));if(counter)counter.textContent=ta.value.length+' / 300 字'};box.appendChild(ta)}for(let n=1;n<=5;n++)onName('评分/'+n+'星',()=>{state.stars=n;save();paintStars()});['讲解清楚','有耐心','有帮助'].forEach(t=>onName('标签/'+t,()=>{state.reviewTags=state.reviewTags.includes(t)?state.reviewTags.filter(v=>v!==t):[...state.reviewTags,t];named('标签/'+t).forEach(b=>b.classList.toggle('selected',state.reviewTags.includes(t)));save()}));const consent=named('未授权')[0];if(consent)bind(consent,()=>{state.consent=!state.consent;paintConsent();save()},'允许匿名案例授权');named('匿名案例授权').forEach(e=>bind(e,()=>{state.consent=!state.consent;paintConsent();save()},'允许匿名案例授权'));paintConsent();paintStars();onName('操作/close',()=>navigate('chat',true));}
