function paintConsent(){named('未选框').forEach(e=>{e.style.background=state.consent?'#1a71fe':'white';e.innerHTML=state.consent?'<span style="color:white;position:absolute;left:3px;top:-2px;font-size:15px">✓</span>':''});named('匿名案例授权').forEach(e=>{e.setAttribute('role','checkbox');e.setAttribute('aria-checked',String(state.consent));e.setAttribute('aria-pressed',String(state.consent))})}
