function setupPriceSlider(){
 const root=screen.firstElementChild;
 ['双滑块价格范围','选中价格范围'].forEach(n=>named(n).forEach(e=>e.style.display='none'));
 qa('[data-name^="滑块/"]').forEach(e=>e.style.display='none');
 qa('p').filter(e=>['¥10','¥15'].includes(e.textContent.trim())&&!e.closest('[data-name="有人接单确认弹窗"]')).forEach(e=>e.style.display='none');
 const slider=document.createElement('div');slider.className='price-slider';slider.id='price-slider';slider.setAttribute('role','group');slider.setAttribute('aria-label','预期价格区间');
 slider.innerHTML='<div class="price-track"></div><div class="price-fill"></div><button id="price-min" class="price-thumb" role="slider" aria-label="最低价格" aria-valuemin="0" aria-valuemax="29" tabindex="0"></button><button id="price-max" class="price-thumb" role="slider" aria-label="最高价格" aria-valuemin="1" aria-valuemax="30" tabindex="0"></button>';
 const scrim=named('接单遮罩')[0];if(scrim){root.insertBefore(slider,scrim);slider.inert=true;slider.style.zIndex='0'}else root.appendChild(slider);const low=q('#price-min'),high=q('#price-max');let active=null;
 const draw=()=>{low.style.left=(state.min/30*100)+'%';high.style.left=(state.max/30*100)+'%';low.textContent='¥'+state.min;high.textContent='¥'+state.max;low.setAttribute('aria-valuenow',state.min);low.setAttribute('aria-valuemax',state.max-1);low.setAttribute('aria-valuetext',state.min+'元');high.setAttribute('aria-valuenow',state.max);high.setAttribute('aria-valuemin',state.min+1);high.setAttribute('aria-valuetext',state.max+'元');const fill=q('.price-fill',slider);fill.style.left=(state.min/30*100)+'%';fill.style.width=((state.max-state.min)/30*100)+'%'};
 const set=(which,value)=>{value=Math.max(0,Math.min(30,Math.round(value)));if(which===low)state.min=Math.min(value,state.max-1);else state.max=Math.max(value,state.min+1);draw();save()};
 const position=e=>{const b=slider.getBoundingClientRect();return (e.clientX-b.left)/b.width*30};
 slider.onpointerdown=e=>{e.preventDefault();clearTimeout(timer);const value=position(e);active=e.target.closest('.price-thumb')||((Math.abs(value-state.min)<=Math.abs(value-state.max))?low:high);active.focus({preventScroll:true});low.style.zIndex=active===low?'3':'2';high.style.zIndex=active===high?'3':'2';slider.setPointerCapture(e.pointerId);set(active,value)};
 slider.onpointermove=e=>{if(active)set(active,position(e))};
 const end=()=>{active=null;save()};slider.onpointerup=end;slider.onpointercancel=end;
 for(const thumb of [low,high]){thumb.onkeydown=e=>{let next=thumb===low?state.min:state.max;if(['ArrowLeft','ArrowDown'].includes(e.key))next--;else if(['ArrowRight','ArrowUp'].includes(e.key))next++;else if(e.key==='Home')next=0;else if(e.key==='End')next=30;else return;e.preventDefault();clearTimeout(timer);set(thumb,next)};thumb.onclick=e=>e.preventDefault()}
 draw();
}
