function chooseProviderSkill(skill){const p=providerState();if(p.selectedSkill!==skill){p.selectedSkill=skill;p.answers=[];p.answerDraft=''}save();render()}
function otherProviderSkill(){showSheet('其他技能','<label>技能名称<input type="text" id="provider-custom-skill" maxlength="24" placeholder="填写你擅长的技能" aria-label="技能名称"></label><button class="primary" id="provider-custom-save">使用该技能</button>',m=>q('#provider-custom-save',m).onclick=()=>{const skill=q('#provider-custom-skill',m).value.trim();if(!skill){toast('请填写技能名称');return}closeSheet();chooseProviderSkill(skill)})}
function setupProviderSkill(){const p=providerState();qa('[data-name^="选择技能/"]').forEach(b=>{const skill=b.dataset.name.split('/')[1];b.classList.toggle('selected',p.selectedSkill===skill);bind(b,()=>skill==='其他技能'?otherProviderSkill():chooseProviderSkill(skill),skill);b.setAttribute('aria-pressed',String(p.selectedSkill===skill))});const selected=named('当前所选技能')[0];if(selected){const ps=qa('p',selected);ps.at(-1).textContent=p.selectedSkill||'请选择一项技能'}
 const material=named('上传资质材料')[0];if(material){const hint=qa('p',material).find(t=>t.textContent.includes('支持图片'));if(hint)hint.textContent=p.certificates.length?'已添加 '+p.certificates.length+' 份材料 · 点击管理':'支持图片或 PDF · 材料仅保存在本地';}
 onName('上传证书',providerCertificates);pButton('下一步：AI 技能问答',()=>{if(!p.selectedSkill){toast('请先选择你擅长的技能');return}navigate('providerQA')});
}
function providerCertificates(){const p=providerState();showSheet('证书与相关材料','<p>演示材料仅在本地读取，不会上传。最多 3 个文件，每个不超过 8 MB。</p><div id="provider-files"></div><label class="provider-file-label">选择图片或 PDF<input id="provider-upload" type="file" accept="image/*,.pdf,application/pdf" multiple aria-label="选择证书或资质材料"></label>',m=>{q('#provider-files',m).innerHTML=p.certificates.map(f=>'<div class="row"><button class="provider-file-name" data-file="'+esc(f.id)+'">'+esc(f.name)+'</button><button data-remove-file="'+esc(f.id)+'" aria-label="移除 '+esc(f.name)+'">移除</button></div>').join('');qa('[data-remove-file]',m).forEach(b=>b.onclick=()=>{p.certificates=p.certificates.filter(f=>f.id!==b.dataset.removeFile);save();providerCertificates();render()});qa('[data-file]',m).forEach(b=>b.onclick=()=>previewProviderFile(b.dataset.file));q('#provider-upload',m).onchange=async e=>{const files=[...e.target.files];if(!files.length)return;if(files.length+p.certificates.length>3){toast('最多添加 3 个材料');return}if(files.some(f=>f.size>8*1024*1024)){toast('单个材料不能超过 8 MB');return}if(files.some(f=>!f.type.startsWith('image/')&&!f.name.toLowerCase().endsWith('.pdf'))){toast('请选择图片或 PDF 文件');return}const items=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('读取失败'));reader.onload=()=>resolve({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),name:f.name,size:f.size,type:f.type||'application/pdf',data:reader.result});reader.readAsDataURL(f)}))).catch(()=>null);if(!items){toast('材料读取失败，请重新选择');return}if(providerState()!==p)return;p.certificates.push(...items);save();closeSheet();render();toast('已添加材料，仅用于本地演示')}})}
function previewProviderFile(id){const file=providerState().certificates.find(f=>f.id===id);if(!file)return;if(!file.data){toast('材料名称已保留，预览需重新选择原文件');return}showSheet(file.name,file.type.startsWith('image/')?'<img class="provider-file-preview" src="'+file.data+'" alt="资质材料预览">':'<p>PDF 已读取，可下载查看。</p><a class="primary" download="'+esc(file.name)+'" href="'+file.data+'">下载 PDF 材料</a>')}
function providerQuestions(){const p=providerState();return PROVIDER_QUESTIONS[p.selectedSkill]||['请说明你在“'+p.selectedSkill+'”中常见问题的判断步骤与操作注意事项。','如果最初的方法不奏效，你会如何继续判断，并向求助者解释下一步？']}
function readProviderAnswer(){const input=q('#provider-answer');if(input){providerState().answerDraft=input.value;save()}}
function setupProviderQA(){const p=providerState(),questions=providerQuestions(),done=p.answers.length>=questions.length,index=Math.min(p.answers.length,questions.length-1);const context=named('本次验证技能')[0];if(context){const ps=qa('p',context);ps[1].textContent=p.selectedSkill;ps[2].textContent='模拟问答，不进行真实 AI 评估或资质认证。'}const ai=named('AI提问')[0];if(ai){const ps=qa('p',ai);ps[0].textContent=done?'演示问答已完成':'模拟 AI 提问 · '+(index+1)+' / '+questions.length;ps.at(-1).textContent=questions[index]}
 const field=named('回答输入')[0];if(field){field.innerHTML='<textarea id="provider-answer" class="provider-answer" maxlength="1000" aria-label="技能问答回答" placeholder="输入你的判断依据、处理顺序与注意事项…"></textarea>';const input=q('textarea',field);input.value=done?p.answers.at(-1).answer:p.answerDraft;input.readOnly=done;input.oninput=readProviderAnswer}
 const answer=named('我的回答')[0];if(answer){const note=qa('p',answer).find(t=>t.textContent.includes('AI 问答会'));if(note)note.textContent=done?'已完成两道演示题，可查看回答或提交模拟验证。':'回答会保存在本地；本演示不判定答案真伪。'}
 const send=named('主流程组件/按钮').find(b=>b.textContent.trim()==='发送回答');if(send){send.querySelector('p').textContent=done?'查看已填写的回答':'发送回答';bind(send,()=>done?providerAnswers():sendProviderAnswer(),done?'查看已填写的回答':'发送回答')}
 const submit=named('主流程组件/按钮').find(b=>b.textContent.trim()==='提交资质验证');if(submit){submit.disabled=!done;submit.setAttribute('aria-disabled',String(!done));submit.classList.toggle('provider-disabled',!done);bind(submit,submitProviderVerification,'提交资质验证')}
}
function sendProviderAnswer(){const p=providerState();readProviderAnswer();if(!p.answerDraft.trim()){toast('请先填写回答');q('#provider-answer')?.focus();return}const questions=providerQuestions();if(p.answers.length>=questions.length)return;p.answers.push({question:questions[p.answers.length],answer:p.answerDraft.trim(),skill:p.selectedSkill});p.answerDraft='';save();render();toast(p.answers.length<questions.length?'回答已保存，请继续下一题':'演示问答已完成，可以提交模拟验证')}
function providerAnswers(){const p=providerState();showSheet('已填写的回答',p.answers.map((a,i)=>'<h3>第 '+(i+1)+' 题</h3><p>'+esc(a.question)+'</p><p class="provider-answer-review">'+esc(a.answer)+'</p>').join('')+'<button class="secondary" id="provider-redo">重新作答</button>',m=>q('#provider-redo',m).onclick=()=>{p.answers=[];p.answerDraft='';save();closeSheet();render()})}
let providerVerifying=false;
function submitProviderVerification(){const p=providerState();if(providerVerifying)return;const verifyingSkill=p.selectedSkill;if(p.answers.length<providerQuestions().length){toast('请先完成两道演示问答');return}providerVerifying=true;const submit=named('主流程组件/按钮').find(b=>b.textContent.trim()==='提交资质验证');if(submit){submit.disabled=true;submit.querySelector('p').textContent='正在模拟验证…';submit.setAttribute('aria-busy','true')}setTimeout(()=>{providerVerifying=false;if(providerState()!==p||p.selectedSkill!==verifyingSkill||p.answers.length<providerQuestions().length)return;p.verified=true;p.verifiedSkill=verifyingSkill;save();if(current==='providerQA')navigate('providerFeed',true);toast('模拟验证已完成，仅切换本地演示状态')},900)}
function providerNeed(){return PROVIDER_NEEDS.find(n=>n.id===providerState().selectedNeedId)}
function openProviderNeed(id){const p=providerState();p.selectedNeedId=id;save();navigate('providerDetail')}
function setupProviderFeed(){const p=providerState();const body=named('页面内容')[0];if(body){const status=qa('p',body).find(t=>/已通过资质验证|模拟资质已验证/.test(t.textContent));if(status)status.textContent='已通过资质验证，可查看问题并报价'}qa('[data-name^="用户求助/"]').forEach((card,index)=>{const need=PROVIDER_NEEDS[index];if(need)bind(card,()=>openProviderNeed(need.id),'查看求助：'+need.title)});const status=body&&qa('p',body).find(t=>/已通过资质验证|模拟资质已验证/.test(t.textContent));if(status)bind(status,()=>showSheet('演示验证状态','<p>当前仅为本地模拟验证，不代表真实身份、证书或技能已通过审核。</p><p>验证技能：'+esc(p.verifiedSkill)+'</p><button class="secondary" id="provider-reverify">重新填写验证资料</button>',m=>q('#provider-reverify',m).onclick=()=>navigate('providerSkill')),'查看验证状态')}
function readProviderQuote(){const input=q('#provider-quote');const need=providerNeed();if(input&&need){providerState().quoteDrafts[need.id]=input.value;save()}}
function setupProviderDetail(){const need=providerNeed(),p=providerState();if(!need){navigate('providerFeed',true);return}const top=named('问题概况')[0];if(top){const title=qa('p',top)[0];title.textContent=need.title;title.title=need.title;const tags=named('问题标签',top)[0];if(tags)tags.innerHTML=need.tags.map(t=>'<span class="provider-data-tag">'+esc(t)+'</span>').join('');qa('p',top).at(-1).textContent=need.name+' · '+need.time+'发布 · '+need.mode}
 const detail=named('问题描述')[0];if(detail){const ps=qa('p',detail);ps.find(t=>t.textContent.includes('电脑使用中'))?.remove();const desc=document.createElement('p');desc.className='provider-description';desc.textContent=need.detail;detail.insertBefore(desc,detail.children[1]);for(const [name,value] of [['信息/期望帮助',need.help],['信息/已尝试',need.tried]]){const row=named(name,detail)[0];if(row)qa('p',row).at(-1).textContent=value}}
 const offer=named('预算与报价')[0];if(offer){const label=qa('p',offer).find(t=>t.textContent.includes('用户预算'));if(label)label.textContent='用户预算 ¥'+need.min+'–'+need.max+' / 次';const input=named('报价输入',offer)[0];if(input){input.innerHTML='<label class="provider-quote-label" for="provider-quote">我的报价</label><div class="provider-quote-value"><span class="provider-currency">¥</span><input id="provider-quote" type="number" step="1" min="1" max="9999" inputmode="numeric" aria-label="我的报价"><span class="provider-quote-unit">/ 次</span></div>';q('#provider-quote',input).value=p.quoteDrafts[need.id]??need.price;q('#provider-quote',input).oninput=readProviderQuote}}
 const existing=p.quotes.find(x=>x.needId===need.id);const submit=named('主流程组件/按钮').find(b=>b.textContent.trim()==='提交报价');if(existing){if(submit){submit.disabled=true;submit.classList.add('provider-disabled');submit.querySelector('p').textContent='已发送模拟报价'}if(offer)pNotice('已模拟提交 ¥'+existing.amount+' / 次，等待求助者选择。',offer);q('#provider-quote').disabled=true}else if(submit)bind(submit,submitProviderQuote,'提交报价');
}
let providerQuoting=false;
function submitProviderQuote(){const need=providerNeed(),p=providerState();if(!p.verified){providerEntry();return}if(!need||providerQuoting)return;readProviderQuote();const raw=p.quoteDrafts[need.id],amount=Number(raw);if(!raw||!Number.isInteger(amount)||amount<=0||amount>9999){toast('请输入 1–9999 的整数报价');q('#provider-quote')?.focus();return}if(p.quotes.some(x=>x.needId===need.id)){toast('本次求助已发送过模拟报价');return}if(amount<need.min||amount>need.max){confirmSheet('报价超出用户预期范围','用户预期为 ¥'+need.min+'–'+need.max+' / 次，仍要发送 ¥'+amount+' 的模拟报价吗？','仍然发送',()=>sendProviderQuote(need,amount));return}sendProviderQuote(need,amount)}
function sendProviderQuote(need,amount){const owner=providerState();if(providerQuoting)return;providerQuoting=true;const button=named('主流程组件/按钮').find(b=>b.textContent.trim()==='提交报价');if(button){button.disabled=true;button.querySelector('p').textContent='正在发送…'}setTimeout(()=>{providerQuoting=false;if(providerState()!==owner)return;if(!owner.quotes.some(x=>x.needId===need.id))owner.quotes.push({needId:need.id,title:need.title,amount,status:'simulated_sent'});save();if(current==='providerDetail'&&providerNeed()?.id===need.id)render();toast('已发送模拟报价，不会产生真实订单或扣款')},650)}
function setupProvider(){onName('操作/back',providerBack);if(current==='providerSkill')setupProviderSkill();if(current==='providerQA')setupProviderQA();if(current==='providerFeed')setupProviderFeed();if(current==='providerDetail')setupProviderDetail();qa('button,[role="button"]').forEach(e=>{if(!e.getAttribute('aria-label'))e.setAttribute('aria-label',e.dataset.name||e.textContent.trim())})}
if(location.hash.slice(1).startsWith('provider')&&routeIds[location.hash.slice(1)])navigate(location.hash.slice(1),true);

/* Message center and anonymous case detail routes. All service records are local demo data. */
Object.assign(routeIds,{messages:'183:1774',caseDetail:'183:1896',historyChat:'183:2096'});
const CASE_LIBRARY=[];
const HISTORY_CONVERSATIONS=[];
function centerState(){if(!state.messageReads)state.messageReads={};if(!state.caseBookmarks)state.caseBookmarks=[];return state.messageReads}
function currentReadKey(){return 'current-'+(state.messageGeneration||'initial')}
function conversationUnread(id){const reads=centerState();if(reads[id==='current'?currentReadKey():id])return 0;return id==='notice'?1:id==='current'?1:HISTORY_CONVERSATIONS.find(c=>c.id===id)?.unread||0}
function readConversation(id){centerState()[id==='current'?currentReadKey():id]=true;save()}
function prepareHubRoute(route){if(route==='caseDetail')routeIds.caseDetail=(CASE_LIBRARY.find(c=>c.id===state.caseSelection)||CASE_LIBRARY[0]).frame;if(route==='historyChat'){const h=HISTORY_CONVERSATIONS.find(h=>h.id===state.historySelection);if(!h)return 'messages';routeIds.historyChat=h.frame}return route}
function hubNav(){qa('[data-name^="导航/"]').forEach(e=>bind(e,()=>navigate(({首页:'home',全部服务:'services',求助:'method',消息:'messages',我的:'profile'})[e.dataset.name.split('/')[1]])))}
function openCurrentConversation(){readConversation('current');if(state.order==='none'){navigate('method');return}if(state.order==='matching'){navigate('matching');return}navigate('chat')}
function openHistoryConversation(id){state.historySelection=id;readConversation(id);navigate('historyChat')}
function serviceNotices(){readConversation('notice');if(current==='messages')render();const status={none:'暂无进行中的求助。发布求助后，服务进展会在这里更新。',matching:'求助已发布，正在等待真实服务者接单。',pending:'已收到接单，请确认服务者与报价后开始沟通。',active:'已确认接单，当前正在进行一对一服务。',review:'本次服务待评价，可从订单入口继续填写。',completed:'服务已完成，评价已保存到“我的评价”。',cancelled:'本次求助已取消。'};showSheet('服务通知','<p>'+esc(status[state.order]||status.none)+'</p>'+(state.title?'<h3>'+esc(state.title)+'</h3>':'')+'<button class="primary" id="notice-orders">查看求助订单</button>',m=>q('#notice-orders',m).onclick=()=>ordersSheet())}
function setupMessageList(){hubNav();const reads=centerState(),currentRow=named('会话/current')[0];const rows=qa('[data-name^="会话/"]');if(state.order==='none')currentRow?.remove();else if(currentRow){const ps=qa('p',currentRow),last=state.messages.at(-1);ps[0].textContent=state.provider;ps[1].textContent='当前';ps[2].textContent=last?.text||(state.order==='pending'?'收到接单，请先确认服务信息':state.detail||'点击查看当前求助进展');ps[3].textContent=({matching:'匹配中',pending:'待确认',active:'服务中',review:'待评价',completed:'已完成',cancelled:'已取消'})[state.order]+' · '+state.title;ps[2].classList.add('conversation-preview');ps[3].classList.add('conversation-preview');if(state.provider==='阿周'){const img=q('img',currentRow);if(img)img.src=getAsset('82:718','图片/self')}bind(currentRow,openCurrentConversation,'打开当前会话：'+state.provider)}
 const notice=named('服务通知')[0];bind(notice,serviceNotices,'查看服务通知');const np=notice&&qa('p',notice).at(-1);if(np)np.textContent=conversationUnread('notice')?'1 条未读 · 查看通知':'查看通知';
 for(const row of rows){if(!row.isConnected)continue;const id=row.dataset.name.slice('会话/'.length),unread=conversationUnread(id),hint=named('未读提示',row)[0];if(hint){hint.textContent=unread?'未读 '+unread:'';hint.style.display=unread?'':'none'}if(id!=='current')bind(row,()=>openHistoryConversation(id),'打开历史会话：'+HISTORY_CONVERSATIONS.find(h=>h.id===id)?.name)}
 const header=named('顶部导航')[0],title=header&&qa('p',header)[0],count=conversationUnread('notice')+HISTORY_CONVERSATIONS.reduce((sum,h)=>sum+conversationUnread(h.id),0)+(state.order==='none'?0:conversationUnread('current'));if(title)title.textContent='消息'+(count?' ('+count+')':'');
 onName('清除未读',()=>{['notice','current',...HISTORY_CONVERSATIONS.map(h=>h.id)].forEach(readConversation);render();toast('全部消息已标记为已读')});
 const search=named('消息搜索')[0];if(search){q('p',search)?.remove();const input=document.createElement('input');input.type='search';input.className='field message-search-field';input.placeholder='搜索联系人或问题';input.setAttribute('aria-label','搜索联系人或问题');search.appendChild(input);const empty=document.createElement('p');empty.className='message-empty';empty.textContent='没有找到相关会话，试试其他联系人或问题关键词。';empty.hidden=true;named('消息列表内容')[0].appendChild(empty);input.oninput=()=>{const value=input.value.trim().toLowerCase();const items=[notice,...qa('[data-name^="会话/"]')];let visible=0;for(const row of items){const match=!value||row.textContent.toLowerCase().includes(value);row.style.display=match?'':'none';if(match)visible++}empty.hidden=visible>0};}
}
function setupHistoryChat(){onName('操作/back',()=>navigate('messages',true));qa('[data-name="主流程组件/按钮"]').forEach(e=>bind(e,()=>navigate('method'),'发起新求助'));const top=named('顶部导航')[0];if(top){const ended=qa('p',top).find(p=>p.textContent==='已结束');if(ended){ended.removeAttribute('role');ended.removeAttribute('tabindex');ended.style.cursor='default'}}}
function openCaseByTitle(title=''){const c=CASE_LIBRARY.find(c=>c.title===title)||CASE_LIBRARY[0];if(!c){toast('案例库暂无已发布内容');return}state.caseSelection=c.id;save();navigate('caseDetail')}
function setupCaseDetail(){centerState();const c=CASE_LIBRARY.find(c=>c.id===state.caseSelection)||CASE_LIBRARY[0];if(!c){back();return}state.caseSelection=c.id;onName('操作/back',back);onName('收藏案例',()=>{state.caseBookmarks=state.caseBookmarks.includes(c.id)?state.caseBookmarks.filter(id=>id!==c.id):[...state.caseBookmarks,c.id];save();render();toast(state.caseBookmarks.includes(c.id)?'已收藏案例':'已取消收藏')});const collect=named('收藏案例')[0];if(collect){q('p',collect).textContent=state.caseBookmarks.includes(c.id)?'已收藏':'收藏';collect.setAttribute('aria-pressed',String(state.caseBookmarks.includes(c.id)))}}

if(['messages','caseDetail','historyChat'].includes(location.hash.slice(1)))navigate(location.hash.slice(1),true);
